media.css:
[data-ui-unit="media"].product-media {
  margin: 0;
}

[data-ui-unit="media"].product-media img {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: 44% center;
  border-radius: 0;
}

@media (min-width: 701px) {
  [data-ui-unit="media"].product-media img {
    border-radius: 8px;
  }
}

identity.css:
[data-ui-unit="identity"].product-identity[data-ui-unit="identity"] {
  padding-top: 24px;
  padding-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .eyebrow {
  display: inline-block;
  font-size: 14px;
  color: #60606a;
  margin-bottom: 8px;
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: #202024;
  margin-bottom: 12px;
}

[data-ui-unit="identity"].product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: #202024;
  margin-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: #555560;
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
}

[data-ui-unit="identity"].product-identity .description {
  font-size: 15px;
  line-height: 1.75;
  color: #202024;
  margin-top: 20px;
  margin-bottom: 0;
}

@media (min-width: 701px) {
  [data-ui-unit="identity"].product-identity[data-ui-unit="identity"] {
    padding-top: 0;
  }

  [data-ui-unit="identity"].product-identity .title {
    font-size: 28px;
  }
}

booking.css:
[data-ui-unit="booking"] .booking-host {
  padding: 20px 0;
  border-top: 1px solid #ededf0;
}

[data-ui-unit="booking"] .booking-studio {
  display: block;
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  margin-bottom: 4px;
}

[data-ui-unit="booking"] .booking-meta {
  display: block;
  font-size: 14px;
  color: #60606a;
  line-height: 1.4;
}

[data-ui-unit="booking"] .booking-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  margin-top: 20px;
}

[data-ui-unit="booking"] #favorite {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: transparent;
  border: none;
  padding: 0;
  color: #60606a;
}

[data-ui-unit="booking"] #favorite img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

[data-ui-unit="booking"] #book {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 52px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  border-radius: 6px;
  border: none;
}

[data-ui-unit="booking"] .booking-note {
  margin-top: 12px;
  font-size: 14px;
  line-height: 1.6;
  color: #60606a;
}


[data-ui-unit="booking"] #favorite:hover {
  background-color: #f5f5f7;
  color: #202024;
}

[data-ui-unit="booking"] #favorite:active {
  transform: scale(0.95);
}

[data-ui-unit="booking"] #book:hover {
  opacity: 0.9;
}

[data-ui-unit="booking"] #book:active {
  background-color: #3e36b5;
}
